import json
import re
from html import unescape
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
by_number = {s['number']: s for s in sources}
answer = []


def plain(xml):
    return unescape(re.sub(r'<[^>]*>', '', xml or ''))


def replace_once(text, old, new):
    assert text.count(old) == 1, (old, text.count(old))
    return text.replace(old, new, 1)


def effect(kind, measure, description, before, after, unit, population,
           transition, burdens, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure, description=description,
                before=before, after=after, unit=unit,
                affected_population=population,
                conditions_and_transition=transition,
                replacement_or_new_burdens=burdens,
                source_quote=source_quote, proposed_quote=proposed_quote)


def record(number, proposed, reason, notes, classification, assessment,
           limitations, burdens, effects, benefit=None, removed=None,
           repeal_scope=None, reference_assessments=None):
    s = by_number[number]
    o = {k: s[k] for k in ['code_id', 'source_id', 'source_sha256', 'number']}
    o.update(proposed_xml=proposed, reason=reason, review_notes=notes,
             status='retained_unchanged' if proposed is None else 'rewrite_draft')
    o['substantive_impact'] = dict(version=1, classification=classification,
                                 assessment=assessment, scope_limitations=limitations,
                                 new_burdens_review=burdens, effects=effects)
    if proposed is None:
        o['classification'] = 'retained_necessary'
    if benefit is not None:
        o['benefit_review'] = benefit
    if removed:
        o.update(change_type='normative_reduction',
                 reform_policy_id='editorial_direction_2026_10_19',
                 removed_provisions=removed)
    if repeal_scope:
        o.update(change_type='full_repeal',
                 repeal_policy_id='editorial_direction_2026_10_19',
                 repeal_scope=repeal_scope)
    key = s['code_id'] + '|' + s['source_id']
    required = references['requirements'][key]
    assessments = reference_assessments or {}
    assert set(assessments) == set(required), number
    o['reference_checks'] = [dict(target_key=k,
                                  view_sha256=references['targets'][k]['view_sha256'],
                                  assessment=assessments[k]) for k in required]
    for e in effects:
        assert len(e['source_quote']) >= 12 and e['source_quote'] in plain(s['source_xml']), (number, e['source_quote'])
        assert len(e['proposed_quote']) >= 12 and e['proposed_quote'] in plain(proposed), (number, e['proposed_quote'])
    answer.append(o)


